def merge_nodes_between_zeros(head):
    dummy=ListNode(0);tail=dummy;node=head.next;total=0
    while node:
        if node.val==0:
            tail.next=ListNode(total);tail=tail.next;total=0
        else:total+=node.val
        node=node.next
    return dummy.next

